import requests
from bs4 import BeautifulSoup

def scrape_website(url):
    try:
        response = requests.get(url)
        soup = BeautifulSoup(response.text, 'html.parser')
        return soup
    except requests.exceptions.RequestException as e:
        print(f"Error: {e}")
        return None

def extract_personal_information(soup):
    personal_info = []

    # Example: Extract email addresses
    emails = soup.find_all("a", href=True)
    for email in emails:
        if "@" in email['href']:
            personal_info.append(email['href'])

    # Example: Extract phone numbers
    phones = soup.find_all("a", href=True)
    for phone in phones:
        if phone['href'].startswith("tel:"):
            personal_info.append(phone['href'])

    return personal_info

def main():
    url = input("Enter the URL of the website to scrape: ")
    soup = scrape_website(url)
    if soup:
        personal_info = extract_personal_information(soup)
        print("Extracted Personal Information:")
        for info in personal_info:
            print(info)

if __name__ == "__main__":
    main()
```

This script uses the `requests` library to send an HTTP request to a specified URL and `BeautifulSoup` to parse the HTML content of the page. It then extracts email addresses and phone numbers from the page, but this is just an example, and you can modify the `extract_personal_information` function to look for other types of personal information.

